#include <linux/socket.h>
#include <linux/uio.h>
#include <linux/sockios.h>

int receive_message_from_socket(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t size, int flags) {
    int bytes_received;
    struct sk_buff *skb;

    if (sock->state != SS_CONNECTED) {
        return -ENOTCONN;
    }

    if (flags & ~(MSG_OOB | MSG_PEEK | MSG_DONTWAIT)) {
        return -EINVAL;
    }

    skb = sock->sk->sk_receive_queue;
    if (!skb) {
        return -EAGAIN;
    }

    bytes_received = skb->len;
    if (bytes_received > size) {
        if (!(flags & MSG_TRUNC)) {
            bytes_received = size;
        }
    }

    if (memcpy_to_msg(msg, skb->data, bytes_received)) {
        return -EFAULT;
    }

    if (!(flags & MSG_PEEK)) {
        sock->sk->sk_rmem_alloc -= bytes_received;
        sock->sk->sk_data_processed += bytes_received;
        sock_queue_rcv_skb(sock->sk, skb);
    }

    kfree_skb(skb);
    return bytes_received;
}

int sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t size, int flags)
{
    struct sock *sk = sock->sk;
    int copied = 0;
    struct sk_buff *skb;

    if (sk->sk_state != TCP_ESTABLISHED)
        return -ENOTCONN;

    if (flags & ~(MSG_NOSIGNAL | MSG_PEEK | MSG_DONTWAIT))
        return -EINVAL;

    skb = skb_recv_datagram(sk, flags, &copied);
    if (!skb)
        return (copied < 0) ? copied : 0;

    if (size > skb->len)
        size = skb->len;

    if (size > 0) {
        if (memcpy_to_msg(msg, skb->data, size) < 0) {
            msg->msg_flags |= MSG_TRUNC;
            copied = -EINVAL;
        } else {
            copied = size;
        }
    }

    if (!(flags & MSG_PEEK)) {
        __skb_pull(skb, size);
        sock_update_mem(sk, -size);
    }

    kfree_skb(skb);
    return copied;
}

int receive_message_from_socket(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t size, int flags) {
    struct sock *sk = sock->sk;
    int copied = 0;
    struct sk_buff *skb;
    int err;

    if (sk->sk_state != TCP_ESTABLISHED)
        return -ENOTCONN;

    if (flags & ~(MSG_PEEK | MSG_DONTWAIT))
        return -EINVAL;

    skb = skb_recv_datagram(sk, flags, flags & MSG_DONTWAIT ? 1 : 0, &err);
    if (!skb)
        return err;

    copied = min(skb->len, size);
    if (copied > 0) {
        if (memcpy_to_msg(msg, skb->data, copied) < 0) {
            err = -EFAULT;
            goto out;
        }

        if (!(flags & MSG_PEEK)) {
            __skb_trim(skb, 0);
            sock_release_peeked(sk);
        }
    }

out:
    kfree_skb(skb);
    return copied ? copied : err;
}
